//! Bit-for-bit parity tests against the Go reference implementation.
//!
//! `go_parity_data.rs` is generated by running the Go package with the same
//! grammars and seeds. A failure here means seeded generation has drifted.

#[derive(Debug)]
pub struct ParityCase {
    pub name: &'static str,
    pub kind: &'static str,
    pub source: &'static str,
    pub start: &'static str,
    pub seed: u64,
    pub tokens: usize,
    pub complete: bool,
    pub expected: &'static str,
}

include!("data/go_parity_data.rs");

#[test]
fn matches_go_reference_output() {
    let mut failures = Vec::new();
    for case in CASES {
        let mut resrap = resrap_rs::Resrap::new();
        let grammar_name = match case.kind {
            "inline" => {
                resrap
                    .parse_grammar(case.name, case.source)
                    .unwrap_or_else(|err| panic!("{}: {}", case.name, err));
                case.name
            }
            "template" => {
                resrap_rs::templates::load(&mut resrap, case.source)
                    .unwrap_or_else(|err| panic!("{}: {}", case.name, err));
                case.source
            }
            other => panic!("{}: unknown fixture kind {:?}", case.name, other),
        };

        let got = if case.complete {
            resrap.generate_complete_with_seeded(grammar_name, case.start, case.seed, case.tokens)
        } else {
            resrap.generate_with_seeded(grammar_name, case.start, case.seed, case.tokens)
        };

        if got != case.expected {
            failures.push(case.name);
        }
    }
    assert!(
        failures.is_empty(),
        "seed parity mismatches: {:?}",
        failures
    );
}
